{
  "command": "sleep 600; ssh -o ConnectTimeout=30 pet \"wc -l < ~/results/batch/batch_progress.jsonl 2>/dev/null; tail -2 ~/batch_run.log 2>/dev/null; pgrep -f pet_batch_run.py >/dev/null && echo RUNNING || echo NOT_RUNNING\"",
  "timeout": 900
}

{
  "command": "ssh -o ConnectTimeout=30 pet \"ps aux | grep -E 'pet_batch_run|pet_detect_track' | grep -v grep; echo ---; ls -la ~/batch_run.log; cat ~/batch_run.log; echo ---; ls -la ~/results/batch/ 2>/dev/null | head -8\"",
  "timeout": 120
}

{
  "command": "ssh -o ConnectTimeout=30 pet \"cd ~/pet-action-recognition && nohup ~/miniconda3/envs/plf/bin/python scripts/pet_batch_run.py --list ~/daytime_list.txt --root ~/results/batch > ~/batch_run.log 2>&1 & disown; sleep 30; echo '--- log:'; cat ~/batch_run.log; echo '--- progress:'; ls -la ~/results/batch/ 2>/dev/null; echo '--- proc:'; pgrep -f 'pet_batch_[r]un' && echo ALIVE || echo DEAD\"",
  "timeout": 120
}

{
  "command": "sleep 90; ssh -o ConnectTimeout=30 pet \"echo '--- log:'; cat ~/batch_run.log 2>/dev/null; echo '--- dir:'; ls ~/results/batch/ 2>/dev/null | head -5; echo '--- proc:'; pgrep -f 'pet_batch_[r]un' >/dev/null && echo ALIVE || echo DEAD\"",
  "timeout": 300
}
